"""Build the bilingual phase-2 overview and attach current results to model pages."""
from pathlib import Path
import json,html,statistics,re,zipfile
ROOT=Path(__file__).resolve().parents[1]
SITE='https://gregorytsai.github.io/zh-en-retrieval-benchmark/'
A=json.loads((ROOT/'data/phase2/analysis.json').read_text('utf-8'))
ORDER=['eng-zho','zho-zho','eng-eng','acord-eng-eng','miracl-zh-zh','miracl-en-en']
LABELS={'eng-zho':('MLQA 中文查英文','MLQA Chinese → English'),'zho-zho':('MLQA 中文查中文','MLQA Chinese → Chinese'),'eng-eng':('MLQA 英文查英文','MLQA English → English'),'acord-eng-eng':('ACORD 英文法律條款','ACORD English legal clauses'),'miracl-zh-zh':('MIRACL 中文子集','MIRACL Chinese subset'),'miracl-en-en':('MIRACL 英文子集','MIRACL English subset')}
def esc(s):return html.escape(str(s))
def tr(zh,en,lang):return en if lang else zh
def name(k,lang=0):return tr('不加重排器','No reranker',lang) if k=='standalone' else (A['names'][k].replace(' 重排',' Reranker') if lang else A['names'][k])
def combo(r,lang=0):return name(r['embedding'],lang)+((' + '+name(r['reranker'],lang)) if r['reranker']!='standalone' else tr('（單獨）',' (alone)',lang))
def group(scope):
 ids=ORDER if scope=='all' else ORDER[:3] if scope=='mlqa' else [scope]
 groups={}
 for r in A['rows']:
  if r['dataset'] in ids:groups.setdefault((r['embedding'],r['reranker']),[]).append(r)
 out=[]
 for (e,rr),rows in groups.items():
  if len(rows)!=len(ids):continue
  item={'embedding':e,'reranker':rr,'queries':sum(r['queries'] for r in rows),'datasets':len(rows),'weight_gib_sum':rows[0]['weight_gib_sum']}
  for k in ['top1','ndcg10','mrr10','recall50','judged_coverage50','total_ms_mean']:item[k]=statistics.mean(r[k] for r in rows)
  item['total_ms_p50']=rows[0]['total_ms_p50'] if len(rows)==1 else None
  item['total_ms_p95']=rows[0]['total_ms_p95'] if len(rows)==1 else None
  out.append(item)
 return sorted(out,key=lambda r:-r['top1'])
def tab(headers,rows):return '<div class="table-scroll" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(path,title,body,lang):
 pre='../' if lang else '';other=('../'+path if lang else 'en/'+path);url=SITE+('en/' if lang else '')+path
 footer=tr('最新測量完成：2026-10-24 01:47（臺灣時間）','Latest measurements completed: 24 Oct 2026, 01:47 Taipei',lang)
 return f'''<!doctype html><html lang="{'en' if lang else 'zh-Hant'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(tr('中英檢索實測：六分項等權平均、14,478筆測量、互動比較與完整開放結果。','Bilingual retrieval benchmark: six-task macro averages, 14,478 measurements, interactive comparisons and reproducible results.',lang))}"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="zh-Hant" href="{SITE+path}"><link rel="alternate" hreflang="en" href="{SITE+'en/'+path}"><link rel="alternate" hreflang="x-default" href="{SITE+path}"><link rel="icon" href="{pre}assets/favicon.svg"><link rel="stylesheet" href="{pre}assets/style.css"><link rel="stylesheet" href="{pre}assets/phase2.css"><meta name="google-site-verification" content="mWQ59Rie_MkAK8-ilMG1MrZ9TO_OLtLBGmgvyCpdYcQ"></head><body><a class="skip" href="#main">{tr('跳至內容','Skip to content',lang)}</a><header><a class="brand" href="index.html"><span class="brandmark">↗</span>{tr('中英檢索實驗室','Bilingual Retrieval Lab',lang)}<span class="brand-sub">LOCAL RETRIEVAL / OCTOBER 2026</span></a><nav><a href="index.html#results">{tr('互動比較','Compare',lang)}</a><a href="index.html#choose">{tr('怎麼選','Choose',lang)}</a><a href="models.html">{tr('模型','Models',lang)}</a><a href="latest-methods.html">{tr('方法與下載','Methods & data',lang)}</a><a href="{other}" lang="{'zh-Hant' if lang else 'en'}">{tr('English','繁體中文',lang)}</a></nav></header><main id="main">{body}</main><footer><div><strong>{tr('中英檢索實驗室','Bilingual Retrieval Lab',lang)}</strong><p>{footer}</p><p>{tr('測量的是檢索排序，不是翻譯或生成回答品質。','Retrieval ranking, not translation or generated-answer quality.',lang)}</p></div><div><a href="https://github.com/gregorytsai/zh-en-retrieval-benchmark">GitHub ↗</a> · <a href="latest-methods.html#license">{tr('授權','Licenses',lang)}</a><p>{tr('聯絡','Contact',lang)}：<a href="mailto:gregorytsai@gmail.com">gregorytsai@gmail.com</a></p></div></footer></body></html>'''
def home(lang):
 t=lambda z,e:tr(z,e,lang);macro=group('all');best=macro[0];base=next(r for r in macro if r['reranker']=='standalone')
 cards=''.join(f'<article class="scorecard"><span>{combo(r,lang)}</span><strong>{r["top1"]*100:.2f}%</strong><small>nDCG@10 {r["ndcg10"]:.3f} · {r["weight_gib_sum"]:.3f} GiB</small></article>' for r in macro)
 body=f'''<section class="phase-hero"><p class="eyebrow">2026-10-24 · MLQA / ACORD / MIRACL</p><h1>{t('先看整體表現，<br>再挑適合你的搜尋組合。','Start with the big picture.<br>Find your retrieval setup.')}</h1><p class="lead">{t('六個測試分項，整理成一眼能比較的綜合平均。要看中文查英文、法律條款或中文搜尋，再往下切換。','Six test conditions, one readable overview. Switch below to cross-language search, legal clauses or Chinese retrieval.')}</p><div class="headline-scores">{cards}</div><p class="macro-note">{t('綜合 Top-1：六分項各占 1/6，只比較六項皆受測的三種組合。ACORD 命中門檻為 2 星以上（與原論文不同）。這是描述性總覽，不代表所有領域或完整 MIRACL 榜單。','Overall Top-1: each condition has weight 1/6; only three setups were tested in all six. ACORD counts ≥2 stars, unlike the paper. This is a descriptive overview, not a universal score or full-corpus MIRACL leaderboard.')} <a href="latest-methods.html#average">{t('平均怎麼算','How averaging works')} →</a></p></section>
<div class="evidence-strip"><div><strong>14,478</strong><span>{t('有效逐題測量','valid measurements')}</span></div><div><strong>2,613</strong><span>{t('資料集內唯一題目','dataset-qualified queries')}</span></div><div><strong>30</strong><span>{t('資料集 × 組合結果','dataset × setup results')}</span></div><div><strong>6</strong><span>{t('測試分項','test conditions')}</span></div></div>
<p class="context-line">Q8_0 · Apple M3 Ultra / Metal · {t('256 GiB 統一記憶體；相同題目會在不同組合重測。','256 GiB unified memory; the same queries are reused across setups.')}</p>
<section id="results"><p class="eyebrow">INTERACTIVE COMPARISON</p><h2>{t('重排增加了多少搜尋效果？','How much does reranking help?')}</h2><p>{t('先選測試範圍，再切換品質指標與重排器。綠色是同一 embedder 單獨使用的分數，橘色是提升；紅色斜線是下降。','Choose a test scope, metric and reranker. Teal is the same embedder alone, orange is a gain, and red hatching shows a loss.')}</p><div class="controls">
<label>{t('測試範圍','Test scope')}<select id="scope"><option value="all">{t('綜合平均｜六分項等權','Overall average | six equal-weight conditions')}</option><option value="mlqa">{t('MLQA 平均｜三方向等權','MLQA average | three equal-weight directions')}</option>{''.join(f'<option value="{k}">{LABELS[k][lang]}</option>' for k in ORDER)}</select></label>
<label>{t('品質指標','Quality metric')}<select id="metric"><option value="top1">{t('Top-1｜第一名命中率','Top-1 | first-result hit rate')}</option><option value="ndcg10">{t('nDCG@10｜前十名排序品質','nDCG@10 | top-ten ranking quality')}</option><option value="mrr10">MRR@10</option><option value="recall50">Recall@50</option></select></label>
<label>{t('顯示重排器','Show reranker')}<select id="reranker"><option value="all">{t('全部已測組合','All tested setups')}</option><option value="standalone">{t('不加重排器','No reranker')}</option><option value="bge-reranker">BGE Reranker v2-m3</option><option value="qwen-reranker-0.6b">Qwen3 Reranker 0.6B</option><option value="qwen-reranker-4b">Qwen3 Reranker 4B</option></select></label></div>
<p id="scope-note" class="note" aria-live="polite"></p><div class="phase-legend"><span class="base-key">{t('單獨檢索','Embedding alone')}</span><span class="gain-key">{t('提升','Gain')}</span><span class="loss-key">{t('下降','Loss')}</span></div><div id="phase-bars" aria-live="polite"></div><p class="small">{t('品質軸固定為 0–100%；nDCG／MRR 以原分數 ×100 顯示，並非命中率。差值是百分點（pp）。','Quality axis: 0–100%; nDCG/MRR are scores ×100, not hit rates. Differences are percentage points (pp).')}</p>
<h3>{t('完整數字，點欄位即可排序','The numbers, sortable by column')}</h3><div id="phase-table" class="table-scroll" tabindex="0"></div><p class="small">{t('綜合時間為各分項「逐題平均時間」的等權平均；分項才提供 p50 / p95，避免把百分位數直接平均。','Aggregate time is the equal-weight mean of task-level mean latencies. p50/p95 appear only for individual tasks; percentiles are never averaged.')}</p><noscript>{t('互動比較需要 JavaScript；下方分項摘要及下載 CSV 可直接閱讀。','Interactive comparison requires JavaScript. Read the static task summary or download the CSV below.')}</noscript></section>'''
 winners=[]
 for d in ORDER:
  rs=group(d);n=max(rs,key=lambda r:r['ndcg10']);top=max(rs,key=lambda r:r['top1']);meta=A['datasets'][d]
  winners.append([LABELS[d][lang],meta['queries'],f'{meta["corpus"]:,}',combo(n,lang),f'{n["ndcg10"]:.3f}',f'{top["top1"]*100:.2f}%',' / '.join(combo(r,lang) for r in rs if abs(r['top1']-top['top1'])<1e-12)])
 body+='<section><h2>'+t('六個分項，重點一次看','All six conditions at a glance')+'</h2><p>'+t('同一指標內比較；法律分級相關性與百科二元相關性並不相同。','Compare within each metric. Legal relevance grades differ from binary encyclopedia labels.')+'</p>'+tab([t('分項','Condition'),t('題數','Queries'),t('文章數','Documents'),t('nDCG 最高點估計','Highest nDCG estimate'),'nDCG@10',t('最高 Top-1','Best Top-1'),t('Top-1 組合','Top-1 setup')],winners)+'</section>'
 body+=f'''<section id="findings"><p class="eyebrow">WHAT THE NEW RUN ADDS</p><h2>{t('三個值得注意的觀察','Three observations worth noticing')}</h2><div class="findings"><article class="finding"><h3>{t('大重排器的收益，取決於你看哪個指標。','A larger reranker helps different metrics differently.')}</h3><p>{t('4B 相對 0.6B 重排器，在六分項的 nDCG 點估計都更高；但法律條款 Top-1 從 19.30% 降為 17.54%。不能把前十名排序改善，說成第一名一定更準。','The 4B reranker has a higher nDCG estimate than 0.6B in all six conditions. Yet legal-clause Top-1 falls from 19.30% to 17.54%. Better top-ten ranking does not guarantee a better first result.')}</p></article><article class="finding"><h3>{t('中文搜尋，加重排也可能沒有明確收益。','Reranking may offer no clear gain for Chinese search.')}</h3><p>{t('MIRACL 中文子集中，0.6B 重排使 Top-1 由 70% 變成 69%，nDCG 則由 0.832 升至 0.839。兩項差異的配對區間都跨零，應先用自己的題目驗證。','On the MIRACL Chinese subset, 0.6B reranking changes Top-1 from 70% to 69%, while nDCG rises from 0.832 to 0.839. Both paired intervals cross zero; validate on your own queries.')}</p></article><article class="finding"><h3>{t('品質更高，也要多等數秒。','Higher ranking quality costs several seconds.')}</h3><p>{t('4B 重排器的時間中位數約為 0.6B 的 5.4–5.9 倍。六分項綜合 Top-1 增加 2.64 百分點，nDCG 增加 0.021；是否值得，取決於服務延遲預算。','Median reranking time is about 5.4–5.9× that of 0.6B. Across six equally weighted conditions, Top-1 improves by 2.64 pp and nDCG by 0.021. The tradeoff depends on your latency budget.')}</p></article></div><p class="small">{t('以上為本機觀察，不宣稱首次發現。信賴區間與公開測量對照見完整說明。','These are local observations, not claims of novelty. See methods for confidence intervals and comparison with published evaluations.')} <a href="latest-methods.html#published">{t('查看研究對照','See research comparison')} →</a></p></section>'''
 recs=[('embeddinggemma-2','standalone',t('輕量起點｜0.289 GiB','Lightweight start | 0.289 GiB'),t('本批最小的受測 embedder。適合先建立低成本基線；只測 MLQA 與 ACORD，沒有 MIRACL 結果。','The smallest embedder in this batch. A low-cost baseline tested on MLQA and ACORD, with no MIRACL results.')),
 ('qwen-4b','standalone',t('低延遲｜3.986 GiB','Low latency | 3.986 GiB'),t('六分項完整受測，MIRACL 查詢總時間中位數約 41 ms。適合不接受每題多等約一秒的服務。','Tested in all six conditions; MIRACL median query time is about 41 ms. Consider it when another second per query is too costly.')),
 ('qwen-4b','qwen-reranker-0.6b',t('品質與時間折衷｜4.581 GiB','Quality/time tradeoff | 4.581 GiB'),t('綜合 Top-1 71.37%。比 4B 重排器快，但 MIRACL 中文未見明確增益；MLQA 也可比較較快的 BGE 重排器（4.578 GiB）。','Overall Top-1 is 71.37%. Faster than 4B reranking, with no clear gain on MIRACL Chinese; for MLQA, also compare the faster BGE reranker (4.578 GiB).')),
 ('qwen-4b','qwen-reranker-4b',t('排序品質優先｜7.972 GiB','Ranking quality first | 7.972 GiB'),t('綜合 Top-1 74.01%、nDCG 0.793。適合能接受較長等待的工作；ACORD 的優勢仍有不確定性。','Overall Top-1 is 74.01% and nDCG 0.793. Consider it when longer waits are acceptable; the ACORD advantage remains uncertain.'))]
 body+='<section id="choose"><p class="eyebrow">CHOOSE BY COST AND NEED</p><h2>'+t('先看模型容量，再看等待時間。','Start with model size, then latency.')+'</h2><div class="recommend-grid">'+''.join(f'<article class="recommend"><p class="eyebrow">{label}</p><h3><a href="models/{e}.html">{name(e,lang)}</a>'+ (f' + <a href="models/{r}.html">{name(r,lang)}</a>' if r!='standalone' else '')+f'</h3><p>{text}</p></article>' for e,r,label,text in recs)+'</div><p class="note">'+t('GiB 是 Q8_0 權重檔合計，不是 RAM／VRAM 最低需求。還需預留執行緩衝、向量索引與系統空間；本次未實測其他硬體或併發。小型 embedder 搭配重排器的舊結果，請看歷史版，不能當成新資料集的實測。','GiB is the sum of Q8_0 weight files, not minimum RAM/VRAM. Allow extra memory for runtime buffers, the vector index and the system. Other hardware and concurrency were not tested. Small-embedder reranker pairs are historical results, not measurements on the new datasets.')+'</p><a href="baseline.html">'+t('檢閱 10/22 歷史版 22 種組合','Review the Oct 22 historical 22-setup comparison')+' →</a></section>'
 body+='<section><h2>'+t('數據、方法與程式，完整保留。','Data, methods and code, ready to inspect.')+'</h2><p>'+t('兩批正式結果可逐題重算；網站沒有重新執行模型。點進各模型頁可查看最新與歷史結果。','Both official batches can be recalculated query by query. The website update did not rerun models. Each model page separates current and historical results.')+'</p><a class="button" href="latest-methods.html#downloads">'+t('下載完整結果與程式','Download results and code')+'</a></section>'
 payload={'lang':lang,'scopes':{k:group(k) for k in ['all','mlqa',*ORDER]},'names':{k:name(k,lang) for k in A['names']},'labels':{k:v[lang] for k,v in LABELS.items()},'datasets':A['datasets']}
 body+='<script id="phase-data" type="application/json">'+json.dumps(payload,ensure_ascii=False).replace('</','<\\/')+'</script><script src="'+('../' if lang else '')+'assets/phase2.js" defer></script>'
 return page('index.html',t('中英檢索實驗室｜最新綜合比較','Bilingual Retrieval Lab | Latest comparison'),body,lang)
def methods(lang):
 t=lambda z,e:tr(z,e,lang);pre='../' if lang else ''
 b='<section class="page-intro"><p class="eyebrow">METHODS / EVIDENCE / DOWNLOADS</p><h1>'+t('看懂平均，也看清限制。','Understand the average and its limits.')+'</h1><p class="lead">'+t('最新結果來自兩批獨立正式測量；這裡保留足以檢查與重現的細節。','The latest results come from two official batches. Here are the details needed to inspect and reproduce them.')+'</p></section>'
 sections=[('average',t('首頁平均怎麼算？','How is the homepage average calculated?'),t('先在每個分項內對所有題目取平均，再把 MLQA 三方向、ACORD、MIRACL 中英文共六個分項的分數相加除以六。每分項各占 16.67%；按資料家族看，MLQA 占 50%、MIRACL 占 33.33%、ACORD 占 16.67%，不是三個家族等權。僅比較六分項皆有測量的三種 Qwen 4B embedding 組合；缺測不補零，也不以不同分母排名。MLQA 平均則是三方向各占 1/3，包含六種配置。','First average over queries within each condition, then average the six condition scores: three MLQA directions, ACORD, and two MIRACL languages. Each condition weighs 16.67%; by dataset family this is 50% MLQA, 33.33% MIRACL and 16.67% ACORD, not equal family weights. Only the three Qwen 4B embedding setups tested in all six are compared. Missing runs are not zero-filled or ranked with different denominators. The MLQA average weights its three directions equally and includes six setups.')),
 ('metrics',t('Top-1 與 nDCG 回答不同問題','Top-1 and nDCG answer different questions'),t('Top-1 是第一篇文章達到本測試相關門檻的比例。MRR@10 看第一篇相關文章在前十名的位置；nDCG@10 綜合前十名排序。MLQA／MIRACL 採二元相關性；ACORD 保留 0–4 等級，nDCG 使用 2^grade−1，Top-1 則以 grade≥1 判定。未標註文件在公式中沒有相關性增益，但不表示人工判定它不相關。綜合 nDCG 混合不同標註方式，僅供描述性總覽，不能解讀成跨領域的絕對準確率。','Top-1 is the fraction whose first document meets this study’s relevance threshold. MRR@10 measures the position of the first relevant result; nDCG@10 evaluates the top-ten order. MLQA/MIRACL use binary labels. ACORD retains grades 0–4 with nDCG gain 2^grade−1, while Top-1 uses grade≥1. Unjudged documents receive no relevance gain in the calculation, but are not human-confirmed negatives. Macro nDCG mixes labeling schemes and is descriptive, not a cross-domain accuracy rate.')),
 ('scope',t('哪些資料納入，哪些沒有？','What was included?'),t('第一批使用完整 MLQA validation 三方向（504、504、1,148題）及 ACORD test 57題，六配置共13,278筆；第二批 MIRACL dev 各選200題，三配置共1,200筆。2,613 是資料集內唯一題目數，不是去除跨語對齊後的獨立問題數。MLQA 包含舊版每方向100題，因此不是完全未見過的 holdout。MIRACL 文章庫是所有 dev 已標註段落的去重聯集（中文3,786、英文7,921篇），不是完整維基語料；Recall@50=100% 只適用於這個子集。QASPER、pilot、失敗與中斷的 attempts 均不納入。','Batch 1 uses all three MLQA validation directions (504, 504 and 1,148 queries) and 57 ACORD test queries: six setups, 13,278 measurements. Batch 2 uses 200 queries per MIRACL dev language: three setups, 1,200 measurements. The 2,613 count is unique within datasets, not independent questions after cross-language deduplication. MLQA includes the previous 100 queries per direction, so this is not an untouched holdout. MIRACL uses the union of all dev judged passages (3,786 Chinese, 7,921 English), not the full Wikipedia corpus. Its 100% Recall@50 only applies to this subset. QASPER, pilots, failed and interrupted attempts are excluded.')),
 ('uncertainty',t('區間如何解讀？','How should intervals be read?'),t('逐題配對 bootstrap 共2,000次、seed 20261023；MLQA 以原始 passage 群聚，ACORD 以 parent query，MIRACL 每題一個 cluster。這不是文章層級群聚，且未作多重比較校正。4B 相對0.6B重排的 nDCG 差異，在三個MLQA與兩個MIRACL分項的95%區間高於零；ACORD 跨零。MIRACL 的 Top-1 差異兩方向皆跨零。ACORD 的 Qwen 4B embedding 候選 Recall@50 僅22.39%、標註覆蓋15.89%，重排無法找回候選池外的相關條款；低分不能全部歸因於重排器。首頁綜合平均沒有另算信賴區間，不能套用分項區間或把所有測量列當成獨立樣本。','Paired bootstrap uses 2,000 replicates and seed 20261023: source-passage clusters for MLQA, parent queries for ACORD, and one cluster per query for MIRACL. This is not article-level clustering, and comparisons are not multiplicity-adjusted. The 95% intervals for 4B-versus-0.6B reranker nDCG gains are above zero for three MLQA and two MIRACL conditions; ACORD crosses zero. Both MIRACL Top-1 intervals cross zero. ACORD candidate Recall@50 is only 22.39% with 15.89% judged coverage for Qwen 4B embeddings; reranking cannot recover relevant clauses outside its pool, so low scores are not solely a reranker issue. No confidence interval was computed for the overall macro average; task intervals cannot be reused or all measurements treated as independent samples.')),
 ('timing',t('速度與容量的實測範圍','What latency and size mean'),t('Apple M3 Ultra、256 GiB統一記憶體、Metal全層offload；Q8_0、llama.cpp build883 commit1fd20a7f4、context8192、單一parallel slot、rerank k=50。總時間為 warmed query 的 embedding、exact搜尋與重排時間相加，包含沿用同一embedding cache的分項時間；不含載入、建索引、網路、佇列及production併發。沒有獨立30題×3次延遲重測。容量僅為GGUF檔案加總，沒有尖峰RAM/VRAM或其他硬體速度實測。','Apple M3 Ultra, 256 GiB unified memory, all-layer Metal offload; Q8_0, llama.cpp build 883 commit 1fd20a7f4, context 8192, one parallel slot and rerank k=50. Total time adds warmed query embedding, exact search and reranking stages, including reused embedding-cache stage times. Loading, indexing, network, queuing and production concurrency are excluded. No independent 30-query ×3 latency repeat study was run. Size is GGUF file size, with no peak RAM/VRAM or other-hardware latency measurement.')),
 ('published',t('與公開測量一致嗎？本次補上什麼？','How does this compare with published measurements?'),t('Qwen 官方報告已測量多尺寸 embedding／reranker 的跨任務品質；較大的重排器通常取得較高整體分數。本次六分項中4B重排器的nDCG點估計均高於0.6B，方向相符。新增的價值是固定Q8_0、llama.cpp／Metal、相同Top50候選下，同時呈現容量、延遲與分項差異。MIRACL中文0.6B沒有明確收益、ACORD的Top-1與nDCG排序不同，是值得驗證的本機觀察，並非已證明普遍成立或世界首次。','Qwen reports cross-task results for multiple embedding and reranker sizes; larger rerankers generally score higher overall. The higher 4B nDCG estimates in all six local conditions follow that direction. This study adds size, latency and task-specific tradeoffs under fixed Q8_0, llama.cpp/Metal and the same Top50 candidates. No clear 0.6B gain on MIRACL Chinese, and different Top-1/nDCG rankings on ACORD, are local observations worth further validation, not universal or first-ever discoveries.'))]
 for key,title,text in sections:b+=f'<section id="{key}"><h2>{title}</h2><p>{text}</p>'+('<p><a href="https://arxiv.org/abs/2506.05176">Qwen3 Embedding technical report</a> · <a href="https://huggingface.co/Qwen/Qwen3-Reranker-4B">Official model evaluation</a> · <a href="https://github.com/project-miracl/miracl">MIRACL benchmark</a> · <a href="https://huggingface.co/datasets/theatticusproject/acord">ACORD dataset</a></p>' if key=='published' else '')+'</section>'
 web=json.loads((ROOT/'data/phase2/web-comparison.json').read_text('utf-8'))
 sources={x['id']:x for x in web['sources']}
 b+='<section><h2>'+t('官方評測與本次觀察對照','Published evaluations and local observations')+'</h2>'
 for c in web['conclusions']:
  b+='<h3>'+c['title_en' if lang else 'title_zh']+'</h3><p>'+c['en' if lang else 'zh']+'</p><p class="small">'+ ' · '.join('<a href="'+sources[k]['url']+'">'+sources[k]['title']+'</a>' for k in c['sources'])+'</p>'
 b+=tab(['Reranker','MTEB-R','CMTEB-R','MMTEB-R'],[['Qwen3 0.6B','65.80','71.31','66.36'],['Qwen3 4B','69.76','75.94','72.74']])+'<p class="small">'+t('此表是Qwen官方分數，使用0.6B embedding與Top100候選，不是本站Top-1，也不能與本站分數直接相減。訓練資料包含MIRACL不等於證明dev/test洩漏。','These are Qwen’s official scores using 0.6B embeddings and Top100 candidates, not this site’s Top-1; do not subtract them from local scores. MIRACL appearing in training data does not demonstrate dev/test leakage.')+'</p></section>'
 b+='<section><h2>'+t('完整分項與配對區間','Full task results and paired intervals')+'</h2>'
 for d in ORDER:
  rows=sorted([r for r in A['rows'] if r['dataset']==d],key=lambda r:-r['ndcg10'])
  b+='<details><summary>'+LABELS[d][lang]+'</summary>'+tab([t('配置','Setup'),'Top-1','nDCG@10','MRR@10','Recall@50',t('標註覆蓋@50','Judged @50'),'p50 ms','p95 ms'],[[combo(r,lang),f'{r["top1"]*100:.2f}%',f'{r["ndcg10"]:.4f}',f'{r["mrr10"]:.4f}',f'{r["recall50"]*100:.2f}%',f'{r["judged_coverage50"]*100:.2f}%',f'{r["total_ms_p50"]:.1f}',f'{r["total_ms_p95"]:.1f}'] for r in rows])
  ci=json.loads((ROOT/f'data/phase2/{A["datasets"][d]["batch"]}-confidence.json').read_text('utf-8'))
  b+=tab([t('右側 − 左側','Right − left'),t('指標','Metric'),t('差值（pp）','Difference (pp)'),'95% CI (pp)'],[[r['right']+' − '+r['left'],r['metric'],f'{r["paired_delta_right_minus_left"]*100:+.2f}',f'[{r["bootstrap95"][0]*100:+.2f}, {r["bootstrap95"][1]*100:+.2f}]'] for r in ci if r['dataset']==d])+'</details>'
 b+='</section><section id="downloads"><h2>'+t('完整資料與程式下載','Download data and code')+'</h2><div class="downloads">'
 files=[('phase2-batch1-results.zip',t('第一批：13,278筆完整結果','Batch 1: all 13,278 measurements')),('phase2-batch2-results.zip',t('第二批：1,200筆MIRACL結果','Batch 2: all 1,200 MIRACL measurements')),('phase2-code.zip',t('兩批測試與驗證程式','Both batch runners and verification code')),('phase2-materials.zip',t('測試素材與選題資料','Test materials and selections'))]
 for file,label in files:b+=f'<a class="download" href="{pre}downloads/{file}"><strong>{label}</strong><span>ZIP ↓</span></a>'
 b+='</div><p>'+t('結果ZIP含完整逐題排名、時間、qrels、選題、summary、CI與manifest。素材ZIP含MLQA／ACORD完整適配資料，以及MIRACL問題、標註與corpus IDs；MIRACL文章全文由固定上游來源取得，不在此重包。','Result ZIPs include all query rankings, timings, qrels, selections, summaries, intervals and manifests. Materials include full adapted MLQA/ACORD inputs plus MIRACL queries, labels and corpus IDs. Retrieve MIRACL passage text from pinned upstream sources instead of a repackaged copy here.')+'</p><p>'+f'<a href="{pre}data/phase2/summary.csv">CSV</a> · <a href="{pre}data/phase2/analysis.json">JSON</a> · <a href="{pre}data/phase2/independent-audit.json">{t("獨立稽核","Independent audit")}</a> · <a href="{pre}research/phase2/README.md">{t("重現指引","Reproduction guide")}</a>'+'</p><p><code>python scripts/verify_phase2.py</code> '+t('（需NumPy）重算14,478筆、30組摘要與32個配對區間；不啟動模型。','(requires NumPy) recomputes 14,478 measurements, 30 summaries and 32 paired intervals without starting models.')+'</p></section>'
 b+='<section id="license"><h2>'+t('授權與原始來源','Licenses and provenance')+'</h2><p>'+t('2026-10-24重新查核官方資料卡：MLQA採CC BY-SA 3.0；ACORD採CC BY 4.0，保留The Atticus Project及作者署名、固定版本與轉換說明。MIRACL topics/qrels官方標示Apache 2.0；Wikipedia段落仍須保留上游來源及適用條款，因此公開包提供選題、標註與固定版本下載工具。研究程式MIT不取代第三方素材或模型授權。','Official cards rechecked on 24 Oct 2026: MLQA uses CC BY-SA 3.0; ACORD uses CC BY 4.0 with The Atticus Project/author attribution, pinned revision and adaptation notes. MIRACL topics/qrels are labeled Apache 2.0; Wikipedia passages retain upstream attribution and applicable terms, so the public package provides selections, judgments and a pinned-download helper. The research-code MIT license does not replace third-party data or model licenses.')+'</p><p><a href="https://github.com/facebookresearch/MLQA">MLQA</a> · <a href="https://huggingface.co/datasets/theatticusproject/acord/blob/main/README.md">ACORD</a> · <a href="https://huggingface.co/datasets/miracl/miracl/blob/main/README.md">MIRACL topics/qrels</a> · <a href="https://huggingface.co/datasets/miracl/miracl-corpus">MIRACL corpus</a></p><p>'+t('改動：轉為檢索格式、固定選題與群聚metadata；ACORD星等減1對應0–4。公開結果僅正式accepted主表；排除內部日誌、主機路徑及未完成嘗試。模型權重不隨附。','Adaptations: retrieval formatting, frozen selection and cluster metadata; ACORD stars minus one gives grades 0–4. Public results include accepted main-table measurements only, excluding internal logs, host paths and incomplete attempts. Model weights are not distributed.')+'</p></section>'
 return page('latest-methods.html',t('最新測試方法與完整資料','Latest methods and complete data'),b,lang)
def build():
 for lang in [0,1]:
  folder=ROOT/('en' if lang else '');t=lambda z,e:tr(z,e,lang)
  # Always run after build_site.py generates a fresh baseline in both languages.
  old=(folder/'index.html').read_text('utf-8')
  old=old.replace(SITE+'en/index.html',SITE+'en/baseline.html').replace(SITE+'index.html',SITE+'baseline.html')
  old=old.replace('href="en/index.html"','href="en/baseline.html"').replace('href="../index.html"','href="../baseline.html"')
  old=old.replace('<main id="main">','<main id="main"><p class="note">'+t('歷史結果｜2026-10-22，每方向100題。','Historical results | 22 Oct 2026, 100 queries per direction.')+' <a href="index.html">'+t('看最新綜合比較','View latest comparison')+'</a></p>')
  (folder/'baseline.html').write_text(old,encoding='utf-8')
  for p in [folder/'models.html',folder/'methods.html',folder/'resources.html',*sorted((folder/'models').glob('*.html'))]:
   text=p.read_text('utf-8');prefix='../' if p.parent.name=='models' else ''
   notice='<aside class="note"><strong>'+t('2026-10-24 更新','Updated 24 Oct 2026')+'</strong> · <a href="'+prefix+'index.html">'+t('最新綜合比較','Latest overall comparison')+'</a> · <a href="'+prefix+'latest-methods.html">'+t('新方法、完整資料與程式','New methods, data and code')+'</a></aside>'
   if p.parent.name=='models':
    key=p.stem;rows=[r for r in A['rows'] if key in [r['embedding'],r['reranker']]]
    notice+='<section><h2>'+t('最新兩批實測結果','Latest two-batch results')+'</h2>'
    notice+=tab([t('分項','Condition'),t('組合','Setup'),'Top-1','nDCG@10','p50 ms','p95 ms'],[[LABELS[r['dataset']][lang],combo(r,lang),f'{r["top1"]*100:.2f}%',f'{r["ndcg10"]:.4f}',f'{r["total_ms_p50"]:.1f}',f'{r["total_ms_p95"]:.1f}'] for r in sorted(rows,key=lambda r:(ORDER.index(r['dataset']),-r['ndcg10']))]) if rows else '<p>'+t('此模型沒有參加最新兩批；下方僅保留10/22歷史測量，不代表在新資料集上的表現。','This model was not included in the latest two batches. The Oct 22 results below do not establish its performance on the new datasets.')+'</p>'
    notice+='</section><h2>'+t('模型介紹與10/22歷史結果','Model background and Oct 22 historical results')+'</h2>'
   else:notice+='<p class="note">'+t('下方保留10/22版本的模型介紹、方法或下載資料；最新結果請使用上方連結。','The content below preserves the Oct 22 model overview, methods or downloads. Use the links above for the latest results.')+'</p>'
   text=text.replace('<main id="main">','<main id="main">'+notice)
   text=text.replace('href="'+prefix+'methods.html"','href="'+prefix+'latest-methods.html"')
   p.write_text(text,encoding='utf-8')
  (folder/'index.html').write_text(home(lang),encoding='utf-8')
  (folder/'latest-methods.html').write_text(methods(lang),encoding='utf-8')
 urls=sorted(str(p.relative_to(ROOT)).replace('\\','/') for p in ROOT.rglob('*.html'))
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+SITE+p+'</loc><lastmod>2026-10-24</lastmod></url>' for p in urls)+'</urlset>',encoding='utf-8')
 print('Built latest bilingual overview;',len(urls),'total pages')
if __name__=='__main__':build()
